def transform(grid):
    g=[row[:] for row in grid]
    h,w=len(g),len(g[0]); border=g[0][0]
    inner=[row[1:-1] for row in grid[1:-1]]
    def period(seq):
        for p in range(1,len(seq)+1):
            if all(seq[i]==seq[i%p] for i in range(len(seq))): return p
    rp=period(inner)
    for r in range(1,h-1):
        if 2 in g[r]: g[r]=[border if x==0 else x for x in g[r]]
        else:
            g[r][0]=g[r][1]; g[r][-1]=g[r][-2]
    for c in range(w):
        g[0][c]=0 if g[1][c]==border else g[1][c]
        # Repeat the pattern across a near border, but not across a wide blank margin.
        trailing=0
        for row in reversed(inner):
            if any(row): break
            trailing+=1
        src=g[1+((h-2)%rp)] if trailing==0 else g[h-2]
        g[h-1][c]=border if 2 in src and src[c]==0 else (0 if src[c]==border else src[c])
    return g

def transform(grid):
    g=[row[:] for row in grid]
    h,w=len(g),len(g[0]); border=g[0][0]
    horizontal=any(3 in g[r] for r in range(1,h-1)) and any(g[r][c]==3 for r in range(1,h-1) for c in range(1,w-1)) and sum(g[r].count(3) for r in range(h))>sum(g[r][c]==3 for r in range(h) for c in range(w))/2
    # A long green row means horizontal bars; otherwise green columns.
    horizontal=any(g[r][1:-1].count(3)> (w-2)//2 for r in range(1,h-1))
    if horizontal:
        cols={c for r in range(h) for c in range(w) if g[r][c]==2}
        for r in range(h):
            if 3 in g[r]: g[r]=[3]*w
            elif 2 in g[r]:
                g[r]=[0 if x in (0,border) else x for x in g[r]]
                if grid[r][-2]==2 and grid[r][-3]==2: g[r][-1]=2
            else:
                g[r]=[border if c in cols else 0 for c in range(w)]
                if any(grid[rr][-2]==2 and grid[rr][-3]==2 for rr in range(1,h-1)): g[r][-1]=border
    else:
        cols={c for c in range(w) if any(g[r][c]==3 for r in range(h))}
        for r in range(h):
            if 2 in g[r]: g[r]=[border if x in (0,border) else x for x in g[r]]
            else: g[r]=[3 if c in cols else 0 for c in range(w)]
    if not horizontal:
        inner=g[1:-1]
        if any(inner[-1]):
            rp=next(p for p in range(1,len(inner)+1) if all(inner[i]==inner[i%p] for i in range(len(inner))))
            g[-1]=inner[len(inner)%rp][:]
    return g
